CREATE TABLE `queue` (
  `QueueID` int(11) NOT NULL AUTO_INCREMENT,
  `OrderID` int(11) NOT NULL,
  `QueuePosition` int(11) DEFAULT NULL,
  `QueueStatus` varchar(50) NOT NULL DEFAULT 'waiting',
  `QueueDate` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`QueueID`),
  KEY `fk_queue_order` (`OrderID`),
  KEY `idx_queue_status_position` (`QueueStatus`,`QueuePosition`),
  CONSTRAINT `fk_queue_order` FOREIGN KEY (`OrderID`) REFERENCES `orders` (`OrderID`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_queue_position_positive` CHECK (`QueuePosition` is null or `QueuePosition` > 0)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
